-- Count number of flights operated by each airline

SELECT a.airline_id,
       a.airline_name,
       COUNT(f.flight_id) AS total_flights
FROM Airline a
LEFT JOIN Flight f
    ON a.airline_id = f.airline_id
GROUP BY a.airline_id, a.airline_name;


-- Calculate the average fare for each flight

SELECT f.flight_id,
       AVG(b.fare) AS average_fare
FROM Flight f
LEFT JOIN Booking b
    ON f.flight_id = b.flight_id
GROUP BY f.flight_id;


-- Calculate the total revenue generated by each airline

SELECT a.airline_id,
       a.airline_name,
       SUM(b.fare) AS total_revenue
FROM Airline a
LEFT JOIN Flight f
    ON a.airline_id = f.airline_id
LEFT JOIN Booking b
    ON f.flight_id = b.flight_id
GROUP BY a.airline_id, a.airline_name;


-- Calculate number of bookings made by each passenger

SELECT p.passenger_id,
       p.passenger_name AS passenger_name,
       COUNT(b.booking_id) AS total_bookings
FROM Passenger p
LEFT JOIN Booking b
    ON p.passenger_id = b.passenger_id
GROUP BY p.passenger_id, p.passenger_name;


-- Airlines with more than average number of flights

SELECT a.airline_id,
       a.airline_name,
       COUNT(f.flight_id) AS total_flights
FROM Airline a
LEFT JOIN Flight f
    ON a.airline_id = f.airline_id
GROUP BY a.airline_id, a.airline_name
HAVING COUNT(f.flight_id) > (
    SELECT AVG(flight_count)
    FROM (
        SELECT COUNT(f2.flight_id) AS flight_count
        FROM Airline a2
        LEFT JOIN Flight f2
            ON a2.airline_id = f2.airline_id
        GROUP BY a2.airline_id
    ) AS avg_flights
);


-- Find the total baggage weight for each booking

SELECT b.booking_id,
       SUM(bg.baggage_weight) AS total_baggage_weight
FROM Booking b
JOIN Baggage bg
    ON b.booking_id = bg.booking_id
GROUP BY b.booking_id;


-- Find the total baggage weight for each passenger

SELECT p.passenger_id,
       p.passenger_name AS passenger_name,
       SUM(bg.baggage_weight) AS total_baggage_weight
FROM Passenger p
JOIN Booking b ON p.passenger_id = b.passenger_id
JOIN Baggage bg ON b.booking_id = bg.booking_id
GROUP BY p.passenger_id, p.passenger_name;